update public.preguntas set
    explicacion = v.explicacion::text,
    norma = v.norma::text
from (values
('cap-0018db3ed93d', 'El CAP es obligatorio para el transporte profesional. Los conductores que realizan transporte privado particular, ya sea de viajeros o mercancías, no necesitan el CAP porque no están realizando una actividad de transporte profesional. La velocidad máxima autorizada del vehículo o su masa máxima autorizada no son criterios para la exención del CAP. Tampoco el número de plazas de un autobús es relevante para determinar la necesidad del CAP.', 'RD 1032/2007 Art. 8'),
('cap-007311c5a157', 'El estrés es una reacción compleja que surge de la interacción entre varios factores. El entorno presenta las demandas o situaciones estresantes, mientras que la actitud de la persona influye en cómo percibe y valora esas demandas. Las respuestas fisiológicas son la manifestación física del estrés en el cuerpo. Por lo tanto, todos estos elementos son cruciales para que aparezca el estrés.', NULL),
('cap-00890a51182c', 'El certificado CITES tiene como objetivo principal controlar el comercio internacional de especies de fauna y flora silvestres que están amenazadas de extinción, para asegurar su supervivencia. Esto incluye tanto a los animales como a las plantas, así como sus productos y derivados. El Reglamento Comunitario (CE) 338/97 Art. 4 establece los requisitos para este control. La opción de controlar el comercio internacional de mercancías peligrosas no es correcta, ya que eso se gestiona con otras normativas específicas para el transporte de mercancías peligrosas.', 'Reglamento Comunitario (CE) 338/97 Art. 4'),
('cap-00961566b714', 'El cabeceo es el movimiento de la parte delantera y trasera del camión hacia arriba y hacia abajo, como si asintiera con la cabeza. Este movimiento se produce sobre un eje imaginario que atraviesa el vehículo de lado a lado, es decir, transversal a la dirección de la marcha. No hay que confundirlo con el balanceo, que es el movimiento lateral del camión.', NULL),
('cap-00c12137bf30', 'La fuerza de gravedad es la atracción que ejerce la Tierra sobre todos los objetos, incluyendo el camión, tirando de él hacia abajo. Esta fuerza es constante y afecta directamente al peso del vehículo y a cómo se asienta sobre la carretera. Las otras opciones no describen la atracción terrestre; por ejemplo, la fuerza centrípeta está relacionada con el movimiento en curva, no con la atracción de la Tierra.', NULL),
('cap-00c90b1ff9b0', 'Para que la declaración amistosa de accidente tenga validez y sirva para agilizar los trámites con las aseguradoras, es imprescindible que ambos conductores implicados la firmen. La firma de los dos conductores significa que están de acuerdo con los hechos y los datos reflejados en el documento. Sin la firma de ambos, el documento carece de valor legal como acuerdo entre las partes. Que la declaración amistosa de accidente haga que disminuya el consumo de los vehículos, el número de siniestros o los atascos de tráfico son afirmaciones incorrectas, ya que su función es únicamente administrativa tras un incidente.', 'Convenio CIDE Art. 3'),
('cap-00dddc805e97', 'El capital social mínimo para constituir una sociedad anónima es de 60.000 euros. Este requisito es inamovible y no depende de compromisos futuros ni del tipo de sociedad anónima. Tampoco influye el número de socios en el capital mínimo exigido.', NULL),
('cap-00e9b590ed1a', 'La alcoholemia mide el nivel de alcohol que ha pasado al torrente sanguíneo, que es lo que realmente afecta a la capacidad de conducción. No se refiere a la graduación de la bebida, que es su concentración de alcohol, ni a la cantidad total que se ha bebido en un periodo, ya que no todo el alcohol ingerido pasa a la sangre de inmediato o en su totalidad.', NULL),
('cap-00eafaf31345', 'Las Juntas Arbitrales del Transporte actúan por defecto en controversias de hasta 15.000 euros, salvo que las partes expresamente digan lo contrario. Esto significa que si el conflicto es por una cantidad igual o inferior a 15.000 euros, se entiende que ambas partes aceptan que la Junta resuelva. Si la cuantía es superior a 15.000 euros, es necesario que las partes acuerden explícitamente someterse a la Junta. La opción de 5.000 euros es incorrecta y un error común, ya que ese límite era el anterior y fue actualizado.', NULL),
('cap-012cd3dfbbfc', 'En una empresa grande de transporte de mercancías, todas las ocupaciones mencionadas son habituales. El gerente o director general se encarga de la dirección estratégica de la empresa. El jefe de tráfico organiza las rutas y la flota, y los conductores son esenciales para realizar el transporte. Por tanto, todas las opciones son correctas.', NULL),
('cap-013732e2b3e0', 'El cabeceo es el movimiento de la parte delantera y trasera del vehículo hacia arriba y hacia abajo. Este movimiento se produce por la transferencia de masas: al acelerar, el peso se desplaza hacia atrás, levantando el morro; al frenar, el peso se va hacia adelante, bajando el morro. Cuando el camión experimenta una fuerza lateral, lo que se produce es un balanceo, no un cabeceo.', NULL),
('cap-01c1a9387aa9', 'La sobrecarga de un eje aumenta la inercia del vehículo y la energía cinética, lo que requiere más tiempo y espacio para detenerse. Además, el exceso de peso puede sobrecargar los frenos, reduciendo su eficacia y aumentando la distancia de detención. La idea de que afecta positivamente a la tracción es incorrecta, ya que una sobrecarga excesiva puede comprometer la estabilidad y el agarre.', NULL),
('cap-01c80536c804', 'El ralentizador hidrodinámico es un sistema de frenado auxiliar que se usa para mantener la velocidad del vehículo en descensos prolongados o para reducirla sin usar los frenos de servicio. Al no depender de la fricción, evita que los frenos de rueda se sobrecalienten y pierdan eficacia, lo que se conoce como "fading". Refrigerar los elementos frenantes es una consecuencia de su uso, no su función principal. Aumentar el coeficiente de rozamiento de las zapatas de freno es incorrecto, ya que el ralentizador no actúa sobre las zapatas.', NULL),
('cap-01cda8f76ac5', 'En caso de incendio, lo primero es señalizar la situación con la luz de emergencia para alertar a los demás conductores. Luego, hay que detener el vehículo de forma segura, fuera de la calzada y el arcén si es posible, para no obstaculizar el tráfico ni poner en riesgo a otros. Además, es crucial conocer y tener presentes las salidas de emergencia y cómo usarlas, especialmente si se transportan pasajeros, para una evacuación rápida y segura. Por lo tanto, todas las acciones mencionadas son correctas y necesarias.', NULL),
('cap-01e487e63b4c', 'No es aconsejable pegarse al vehículo de delante porque necesitas espacio para reaccionar si frena de golpe. Mantener la distancia de seguridad es fundamental para evitar colisiones y tener tiempo para maniobrar. Pensar que pegarse ahorra combustible es un error, ya que el riesgo de accidente supera cualquier posible beneficio mínimo.', NULL),
('cap-023a7b9c0b53', 'La resistencia a la rodadura aumenta cuando el neumático está menos inflado porque la superficie de contacto con el suelo es mayor y la deformación del neumático es excesiva. Esto provoca un mayor rozamiento y, por tanto, una mayor resistencia al avance del vehículo. El aumento del consumo de carburante es una consecuencia de la mayor resistencia a la rodadura, no una causa.', NULL),
('cap-02516a57713e', 'Cuando el camión sobrevira, la trayectoria real es más cerrada de lo que el conductor pretende. Esto ocurre porque las ruedas traseras pierden adherencia antes que las delanteras, haciendo que la parte trasera del vehículo se desplace hacia el exterior de la curva. El subviraje es lo contrario, cuando la trayectoria es más abierta de lo deseado. El derrape es una pérdida general de control, y el balanceo es un movimiento lateral sin pérdida de trayectoria.', NULL),
('cap-0253bc30309f', 'Cuando conduces con viento, es crucial estar muy atento al pasar de zonas donde el viento no te afecta, como un túnel o un edificio, a zonas abiertas. En esos cambios, el viento puede golpear el vehículo de repente y desestabilizarlo. Sujetar el volante firmemente y no aumentar la velocidad te ayudará a mantener el control. Pensar que el viento no afecta a la conducción es un error grave que puede provocar un accidente.', NULL),
('cap-028da337bedd', 'La calidad producida se refiere al resultado real de la actividad de transporte, es decir, el nivel de calidad que la empresa consigue entregar en la práctica. Es lo que la empresa realmente hace y cómo lo hace. No es lo que se propone hacer, ni lo que compra, ni lo que el cliente cree que recibe.', NULL),
('cap-02a677b8c032', 'El sistema ASR necesita saber si alguna rueda está perdiendo adherencia para poder actuar. Para ello, los sensores de velocidad de las ruedas son los que le proporcionan esa información directamente. El diferencial, el motor o el grupo cónico no miden directamente el deslizamiento de las ruedas, sino que son componentes del sistema de transmisión o propulsión.', NULL),
('cap-02bac458f9a9', 'La proximidad de una gran población es el factor que más influye en la variación de la intensidad del tráfico, ya que genera un flujo constante de vehículos que entran y salen de la ciudad, con picos en horas punta y descensos en horas valle. El carácter industrial de la zona o la mayor proporción de tráfico pesado pueden aumentar la intensidad general, pero no provocan grandes variaciones a lo largo del día como lo hace una gran población.', NULL),
('cap-030238860197', 'El transporte por carretera es el que más empleo genera porque es el modo más flexible y capilar, llegando a cualquier punto y moviendo la mayor parte de las mercancías. Esto requiere una gran cantidad de conductores, personal de carga y descarga, y personal de gestión y mantenimiento. Otros modos como el ferroviario, aéreo o marítimo, aunque importantes, tienen una infraestructura y operativa que, en comparación, demandan menos personal directo para el movimiento de la carga.', NULL),
('cap-03037caa6ab6', 'No encararse con el agresor es fundamental para evitar que la situación escale y se convierta en violencia física. Mantener la distancia y no confrontar directamente ayuda a proteger tu integridad. Responder al insulto, aunque sea sin perder la calma, puede ser percibido como una provocación y empeorar el conflicto.', NULL),
('cap-0333da85dcd5', 'Cuando las zapatas se calientan demasiado, pierden su capacidad de fricción contra el tambor, un fenómeno conocido como "fading". Esto significa que, aunque pises el pedal, el freno no responderá con la misma fuerza. Por lo tanto, la eficacia del frenado se reduce considerablemente. Pensar que un calentamiento excesivo mejora el frenado es un error, ya que el material de fricción se degrada con el calor extremo.', NULL),
('cap-036704a28a16', 'Para ahorrar carburante, hay que mantener el motor a bajas revoluciones. Esto se consigue utilizando la marcha más larga posible en cada situación, siempre que el motor no se fuerce. Circular variando constantemente el régimen de revoluciones o bajar pendientes con el embrague pisado son prácticas que aumentan el consumo y el desgaste. Llevar la presión de los neumáticos por debajo de lo recomendado es peligroso y aumenta el consumo, no lo reduce.', NULL),
('cap-03c2dd91882c', 'El Reglamento Comunitario (CE) 1/2005 Art. 6.5 establece que solo pueden ser conductores o cuidadores de vehículos que transporten équidos domésticos, bovinos, ovinos, caprinos, porcinos o aves de corral, quienes tengan un certificado de competencia. Esto significa que el certificado es necesario, pero no para todas las especies animales, sino para las mencionadas. La opción que indica que es necesario en todos los casos y para los acompañantes en todos los recorridos es incorrecta porque la normativa especifica las especies y no generaliza a todos los acompañantes en todos los recorridos.', 'Reglamento Comunitario (CE) 1/2005 Art. 6.5'),
('cap-0413ced23916', 'El dispositivo antibloqueo de frenos es universalmente conocido por sus siglas ABS, que provienen del inglés Anti-lock Braking System. Su función principal es evitar que las ruedas se bloqueen durante una frenada brusca, permitiendo al conductor mantener el control de la dirección. El ESP es el control electrónico de estabilidad, que ayuda a evitar derrapes, y el ADR es un acuerdo para el transporte de mercancías peligrosas.', NULL),
('cap-042a45714a0b', 'Las autoridades aduaneras pueden conceder tanto reducciones como exenciones en el importe de la garantía global para el tránsito de la Unión. Esto es posible en determinados supuestos, siempre que el operador cumpla con los criterios establecidos en el Reglamento Comunitario (UE) 952/2013 Art. 95. La opción que dice que no pueden conceder reducciones ni exenciones es incorrecta, ya que la normativa sí contempla estas posibilidades bajo ciertas condiciones.', 'Reglamento Comunitario (UE) 952/2013 Art. 95'),
('cap-0437adc3089c', 'Cuando un neumático revienta, el vehículo pierde estabilidad de forma repentina. Si es una rueda delantera, notarás un fuerte tirón en la dirección hacia el lado de la rueda afectada. Si es una rueda trasera, el vehículo tenderá a irse de atrás hacia ese lado. La dureza excesiva del giro del volante o la tendencia a seguir en línea recta no son síntomas de reventón, sino de otros problemas mecánicos o de la dirección.', NULL),
('cap-043ffbda71af', 'El Reglamento Comunitario (CE) 1/2005 Anexo I establece que las hembras en período de lactancia de las especies bovina, ovina y caprina que no vayan acompañadas de sus crías deben ser ordeñadas a intervalos no superiores a doce horas. Esto es fundamental para su bienestar y para evitarles sufrimiento. Ordeñar cada 2, 4 o 36 horas no cumple con la normativa y podría causarles problemas de salud.', 'Reglamento Comunitario (CE) 1/2005 Anexo I'),
('cap-044d162d90f7', 'La póliza de seguro de responsabilidad civil no es obligatorio llevarla a bordo del vehículo. Lo que sí es obligatorio es que el vehículo tenga un seguro en vigor, pero no es necesario llevar la póliza física. Los demás documentos, como el permiso de circulación, la ficha técnica y los certificados ADR o ATP si aplican, son de porte obligatorio y deben estar siempre en el vehículo.', NULL),
('cap-046a1a7bdb9f', 'Muchos fármacos tienen efectos secundarios que afectan directamente a la capacidad de conducir. La somnolencia es un riesgo evidente, ya que reduce la atención y el tiempo de reacción. Los mareos también son peligrosos porque alteran el equilibrio y la percepción del entorno. La fatiga muscular puede disminuir la fuerza y la coordinación necesarias para manejar el vehículo con seguridad.', NULL),
('cap-047acc18efe8', 'El tacógrafo digital debe medir la distancia con una resolución mínima de 0,1 km. Esto asegura una precisión adecuada para el registro de los trayectos. Una resolución de 1.000 km, 0,5 km o 2.000 km no cumpliría con los requisitos de exactitud necesarios para el control de los tiempos de conducción y descanso. El Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado III, 2.1 (3821/85) establece esta precisión mínima.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado III, 2.1 (3821/85)'),
('cap-04832db17ff1', 'La resistencia aerodinámica aumenta de forma exponencial con la velocidad. Esto significa que si duplicas la velocidad, la resistencia no se duplica, sino que se multiplica por cuatro. Por eso, la resistencia aerodinámica crece con el cuadrado de la velocidad. La opción que dice que no hay relación es incorrecta, ya que la velocidad es el factor principal que influye en la resistencia del aire.', NULL),
('cap-04925e016b4d', 'Las resistencias que intervienen en el movimiento de un vehículo son las que se oponen a su avance. La resistencia aerodinámica es la oposición del aire al movimiento, y la resistencia a la pendiente es la fuerza de la gravedad que tira del vehículo hacia abajo cuando sube una cuesta. Las otras opciones mencionan componentes internos del motor o la transmisión, que generan rozamientos internos, pero no son las resistencias principales que se oponen al movimiento global del vehículo.', NULL),
('cap-04b7353f68de', 'Conducir en la zona de máximo par motor significa que el motor está trabajando de forma más eficiente, entregando la mayor fuerza de giro con el menor esfuerzo. Esto se traduce en un mejor aprovechamiento del carburante, ya que el motor rinde al máximo de su capacidad. Si se desaprovecha el carburante, es porque el motor no está trabajando en su punto óptimo de eficiencia.', NULL),
('cap-050323dfa15d', 'El consumo de combustible es mayor cuando el motor trabaja a su máxima potencia porque en ese punto se le exige el mayor rendimiento y, por tanto, la mayor cantidad de energía. Para generar esa potencia máxima, el motor necesita quemar más combustible. Las relaciones de marchas largas, por el contrario, buscan reducir el consumo al mantener el motor a bajas revoluciones.', NULL),
('cap-053f8a48b15d', 'Para mantener una dieta equilibrada y obtener los nutrientes necesarios, se recomienda consumir tres piezas de fruta al día. Esto asegura un aporte adecuado de vitaminas, minerales y fibra. Consumir solo una o dos piezas a la semana es insuficiente para cubrir las necesidades diarias del organismo.', NULL),
('cap-0561153f65b9', 'La formación continua del CAP sirve para que los conductores profesionales actualicen y repasen los conocimientos que ya adquirieron en la formación inicial. Así se aseguran de mantener sus habilidades y conocimientos al día para seguir ejerciendo la profesión. La formación continua no es para obtener el CAP, sino para renovarlo. La opción de avanzar en la formación previa al permiso de conducir no es correcta porque el CAP es posterior a la obtención del permiso.', NULL),
('cap-0580d0bdef8a', 'La ergonomía es la disciplina que estudia cómo diseñar el entorno de trabajo y las herramientas para que se adapten a las capacidades y limitaciones del ser humano. Su objetivo es optimizar la eficiencia, la seguridad y el bienestar del trabajador. Las otras opciones son errores ortográficos de este término.', NULL),
('cap-059429c674ab', 'El ejercicio físico es muy importante para los conductores profesionales porque su trabajo implica estar sentados durante muchas horas, lo que puede provocar problemas de salud. Mantenerse activo ayuda a prevenir el sedentarismo y sus consecuencias negativas. No es para comprender normas ni analizar información del tráfico, esas son funciones cognitivas que no se mejoran directamente con el ejercicio físico.', NULL),
('cap-05962c96604b', 'Cuando el motor gira a altas revoluciones, el pistón sube y baja muy rápido. Esto significa que el tiempo disponible para que la mezcla de aire y combustible se queme completamente dentro del cilindro es muy corto. Si el combustible no se quema del todo, se pierde eficiencia y potencia. El máximo par motor se consigue a revoluciones medias, no a las más altas.', NULL),
('cap-0597f200f749', 'Siempre hay que tapar a los heridos, incluso en verano, para evitar que pierdan calor corporal. Un herido, por el shock del accidente, puede sufrir hipotermia aunque la temperatura ambiente sea alta. No taparlos solo si hace mucho frío es un error, ya que la pérdida de calor es un riesgo constante. Tampoco hay que preocuparse por el sudor, la prioridad es mantener su temperatura.', NULL),
('cap-05af8e309cbe', 'El buen estado del vehículo es fundamental para la seguridad vial. Un vehículo en óptimas condiciones reduce el riesgo de accidentes, protegiendo así al conductor, a los pasajeros si los hubiera, y a todos los demás usuarios de la carretera. Por lo tanto, la seguridad de todos depende directamente del mantenimiento y buen estado del vehículo. Pensar que solo afecta a una parte es un error, ya que un fallo mecánico puede tener consecuencias para cualquiera.', NULL),
('cap-05e7e89060ce', 'A mayor velocidad, el aire opone más resistencia al avance del camión, lo que se traduce en un mayor rozamiento aerodinámico. Este aumento del rozamiento implica que el motor debe generar más fuerza para contrarrestarlo y mantener la velocidad. Por lo tanto, se necesita más energía para mantener el vehículo en movimiento a velocidades elevadas. No es cierto que el rozamiento disminuya con la velocidad, ya que la resistencia del aire es directamente proporcional al cuadrado de la velocidad.', NULL),
('cap-05ee276f2e57', 'La formación continua para el CAP debe realizarse al menos cada cinco años. Así lo establece el RD 1032/2007 Art. 7.3, que indica que el curso debe repetirse a partir de entonces, al menos, cada cinco años. La opción de que no es necesario renovar la tarjeta es incorrecta, ya que la cualificación profesional tiene una vigencia limitada y requiere formación periódica.', 'RD 1032/2007 Art. 7.3'),
('cap-05f6bc50b2f2', 'Las furgonetas son los vehículos de transporte de mercancías que más accidentes sufren. Esto se debe a su gran número en circulación, a que a menudo son conducidas por personal sin la formación específica de un conductor profesional y a que se utilizan mucho en el reparto urbano, con más interacciones y situaciones de riesgo. Los camiones de gran tonelaje y los vehículos articulados, aunque tienen accidentes más graves, intervienen en menos siniestros en total. Los autobuses de transporte regular, por su parte, tienen una siniestralidad muy baja debido a la profesionalidad de sus conductores y a las rutas fijas.', NULL),
('cap-060379f91861', 'El consumo de carburante está directamente relacionado con las revoluciones del motor, ya que a más revoluciones, más combustible se inyecta para generar potencia. Cada motor tiene un rango óptimo de revoluciones, conocido como "zona económica", donde el consumo es menor para la potencia entregada. Mantener el motor en este rango es clave para ahorrar carburante. La refrigeración de los frenos no tiene impacto directo en el consumo de combustible del motor.', NULL),
('cap-0611c95c233f', 'La omisión de socorro es un delito porque la ley exige que cualquier persona auxilie a quien se encuentre en peligro manifiesto y grave, siempre que no suponga un riesgo para sí mismo o para otros. No es una infracción administrativa, sino un delito tipificado. Tampoco es cierto que solo sea delito si hay muertos, ya que el deber de socorro existe ante cualquier peligro grave. La ayuda no es siempre voluntaria en estos casos, sino una obligación legal.', NULL),
('cap-06255b502020', 'Para que el camión empiece a moverse, la fuerza que genera el motor debe ser mayor que todas las fuerzas que se oponen al movimiento, como el rozamiento o la inercia del vehículo. Si la fuerza del motor no supera esa resistencia, el camión no se moverá. El acelerador no proporciona fuerza, solo regula la que entrega el motor.', NULL),
('cap-06394efc82c9', 'El tacógrafo digital empieza a funcionar correctamente desde su activación. Es en ese momento cuando todas sus funciones de registro y almacenamiento de datos están plenamente operativas y listas para usarse. Que se introduzca por primera vez una tarjeta de conductor no es el inicio de su correcto funcionamiento, ya que el tacógrafo debe estar activado previamente. Tampoco funciona correctamente desde que sale de fábrica, pues necesita ser activado para registrar datos.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado V, 1 (3821/85)'),
('cap-065ef9e781ad', 'En una sociedad de responsabilidad limitada, los socios no responden personalmente de las deudas sociales, lo que significa que su patrimonio personal está protegido. Su responsabilidad se limita al capital que han aportado a la sociedad, tal como establece el RD Legislativo 1/2010 Art. 1.2. La opción de que uno de los socios responda personalmente como socio colectivo es característica de la sociedad comanditaria por acciones, no de la de responsabilidad limitada.', 'RD Legislativo 1/2010 Art. 1.2'),
('cap-066a00904b70', 'Quien contrata con la compañía de seguros es el tomador, que es quien firma la póliza y asume las obligaciones de pago. El asegurado es la persona o cosa sobre la que recae el riesgo cubierto, que puede ser el propio tomador u otra persona. El beneficiario es quien recibe la indemnización en caso de siniestro. Un tercero es cualquier persona ajena al contrato.', 'Ley 50/1980 Art. 7'),
('cap-068e3be84b8f', 'Los costes humanos son los más difíciles de valorar económicamente porque se refieren al sufrimiento, la pérdida de calidad de vida o la muerte, aspectos que no tienen un precio de mercado. Aunque se pueden intentar cuantificar con indemnizaciones, estas nunca reflejan el valor real de una vida o la ausencia de un ser querido. Los costes directos e indirectos, aunque significativos, son más sencillos de calcular al estar relacionados con daños materiales, gastos médicos o pérdidas de producción.', NULL),
('cap-06b5e05dab11', 'La energía cinética es la energía que tiene un cuerpo en movimiento y se mide en julios. La capacidad calorífica del gasoil o de la gasolina se mide en julios por kilogramo y kelvin, no solo en julios. La presión de inflado de los neumáticos se mide en bares o en pascales, que son unidades de presión, no de energía.', NULL),
('cap-06c29ab78bb4', 'Al bajar una pendiente pronunciada con un vehículo pesado, el ralentizador es el sistema más eficaz y seguro para mantener la velocidad controlada. Su uso evita el sobrecalentamiento y el desgaste excesivo del freno de servicio, que debe reservarse para frenadas de emergencia o para detener completamente el vehículo. Utilizar el freno de servicio de forma continuada en una bajada larga puede provocar su fallo por sobrecalentamiento. Bajar en punto muerto es extremadamente peligroso, ya que se pierde el control del vehículo y la capacidad de retención del motor.', NULL),
('cap-0743fd68d6c5', 'La resistencia aerodinámica es la fuerza que el aire ejerce contra el avance del camión. Esta fuerza aumenta significativamente con la velocidad, por lo que es un factor clave en el consumo de combustible a altas velocidades. No se debe confundir con la resistencia que se produce al acelerar o frenar, que es la inercia de la masa del vehículo.', NULL),
('cap-0754f1e7e384', 'Si no puedes usar tu tarjeta de conductor, el Reglamento Comunitario (UE) 165/2014 Art. 35.2 establece que debes imprimir los datos del vehículo al inicio del viaje, identificándote y firmando. Al final del viaje, tienes que imprimir los datos de los tiempos registrados por el tacógrafo, anotar las actividades no registradas y volver a identificarte y firmar. La opción de conducir hasta poder usarla es incorrecta porque la normativa exige registrar las actividades desde el primer momento.', 'Reglamento Comunitario (UE) 165/2014 Art. 35.2'),
('cap-075d402fde1c', 'Voltear a un herido de tráfico es muy peligroso porque podría tener lesiones internas o en la columna vertebral que se agravarían. La prioridad es estabilizar al herido y mantenerlo con vida, y para eso las actuaciones en la primera hora son cruciales. Si no sabes qué hacer, es mejor no actuar para no empeorar la situación.', NULL),
('cap-075fb333ced0', 'El mayor número de fallecidos se da en turismos porque son los vehículos más numerosos en circulación y, por tanto, los que más implicados están en accidentes. Aunque los vehículos pesados y autobuses tienen un riesgo por accidente potencialmente mayor, su menor número en las carreteras hace que el total de víctimas sea inferior. Los ciclomotores, aunque tienen un alto riesgo individual, también son menos numerosos que los turismos.', NULL),
('cap-076f1f5a7ac4', 'El contacto de la carga con tendidos eléctricos de alta tensión provoca directamente un cortocircuito, lo que genera una descarga eléctrica inmediata. Aunque un incendio podría ser una consecuencia secundaria de la descarga, el riesgo más directo e inmediato es la electrocución. La proyección de líquidos o la exposición a tóxicos no tienen relación directa con el contacto eléctrico.', NULL),
('cap-077656c13c58', 'En una colisión entre un vehículo pesado y un turismo, la masa y la inercia del vehículo pesado son mucho mayores. Esto provoca que el turismo absorba la mayor parte de la energía del impacto, deformándose gravemente. Por ello, los ocupantes del turismo son los que sufren las lesiones más graves. Es un error pensar que solo el conductor del turismo sufre daños, ya que todos los ocupantes están expuestos a la misma fuerza del impacto.', NULL),
('cap-07d239d995cd', 'La tecnología e-Call está diseñada para la seguridad en carretera. Su función principal es realizar una llamada de emergencia automática a los servicios de socorro en caso de un accidente grave. Esta llamada incluye datos importantes como la ubicación del vehículo, lo que agiliza la asistencia. La opción que indica que no permite conocer la ubicación del vehículo es incorrecta, ya que la geolocalización es clave para su funcionamiento.', NULL),
('cap-080d9a24f074', 'Para elaborar estadísticas completas y fiables sobre accidentes de tráfico, es fundamental recopilar información de todas las fuentes posibles. Tanto los implicados en el accidente, como los agentes de tráfico que intervienen y los centros sanitarios que atienden a los heridos, poseen datos cruciales para entender las causas y consecuencias de los siniestros. Por ello, la obligación de suministrar esta información recae sobre todos ellos. La opción que solo menciona a los agentes de tráfico es incorrecta porque, aunque su papel es vital, no son los únicos que disponen de información relevante para las estadísticas.', NULL),
('cap-08438f820ac6', 'Los transportes de material para manifestaciones musicales, deportivas o circos, siempre que no tengan fines comerciales, están liberalizados dentro del sistema CEMT. Esto significa que no requieren una autorización CEMT específica para su realización. Es importante recordar que esta liberalización se aplica a los transportes sin ánimo de lucro de estos materiales específicos.', NULL),
('cap-0854bff1c854', 'Se considera transporte de carga fraccionada cuando la mercancía requiere ser manipulada, agrupada o clasificada antes de su carga o después de su descarga. Esto implica que no es una unidad completa que se carga o descarga de una sola vez. La necesidad de estas operaciones previas o posteriores es lo que define este tipo de carga. Que la mercancía viaje en compartimentos diferenciados no es la definición de carga fraccionada, sino una forma de organizar el espacio.', NULL),
('cap-0856bc8f9b06', 'La ergonomía se centra en adaptar el entorno de trabajo a la persona para mejorar su bienestar y eficiencia. Esto incluye el diseño del espacio, las posturas que se adoptan y los movimientos que se realizan para evitar lesiones y fatiga. Las ganancias monetarias, aunque importantes para la empresa y el trabajador, no son un aspecto directo de la ergonomía, que se ocupa de la interacción física y mental del trabajador con su puesto.', NULL),
('cap-08869ae6ace0', 'La aerodinámica es clave porque la resistencia del aire es una de las fuerzas principales que el motor debe vencer, especialmente a velocidades elevadas. Un diseño aerodinámico reduce esta resistencia y, por tanto, el esfuerzo del motor, lo que se traduce directamente en un menor consumo de carburante. El tipo de batería no influye en el consumo de carburante, ya que su función principal es el arranque y el suministro eléctrico a los sistemas del vehículo.', NULL),
('cap-08951a1fb2ac', 'Las letras RND identifican un vehículo refrigerante normal de la clase D. La ''R'' indica que es un vehículo refrigerante, la ''N'' que es de tipo normal, y la ''D'' se refiere a la clase de temperatura. Un vehículo isotermo normal de la clase D se identificaría con las letras IND, no RND.', 'Acuerdo ATP Anejo I, Apéndice 4'),
('cap-0898afbc0d4d', 'Si sientes mucha somnolencia, lo único efectivo es parar y descansar. Moverte en el asiento, abrir las ventanillas o subir la radio son solo distracciones temporales que no eliminan el riesgo de quedarte dormido al volante. La fatiga es muy peligrosa y solo se combate durmiendo.', NULL),
('cap-08c8364fb999', 'El alumbrado del vehículo debe utilizarse siempre entre la puesta y la salida del sol para garantizar la visibilidad del vehículo y la seguridad en la carretera. Es una medida preventiva fundamental para ser visto por otros usuarios de la vía. Utilizar las luces solo cuando las señales de los agentes lo demanden es incorrecto, ya que el uso del alumbrado es una obligación general en ciertas condiciones de luz, independientemente de la presencia de agentes.', NULL),
('cap-08eccf9d4f9b', 'Para comparecer ante una Junta Arbitral del Transporte, no es obligatoria la asistencia de abogado ni de procurador. El RD 1211/1990 Art. 9.6 establece claramente que no es necesaria su presencia. La idea de que se necesita abogado o procurador es un error común, ya que las Juntas de Arbitraje buscan un procedimiento más ágil y accesible para resolver conflictos.', 'RD 1211/1990 Art. 9.6'),
('cap-09200119340c', 'La infracción por inadecuado funcionamiento del aparato de control se produce cuando el transportista es responsable de ese mal funcionamiento. La Ley 16/1987 Art. 140.33 establece que es una infracción muy grave la manipulación del tacógrafo o de otros instrumentos de control para alterar su funcionamiento o mediciones. No se limita solo a averías de tacógrafos digitales, ni a cualquier mal funcionamiento sin más, sino a aquellos casos donde la responsabilidad recae en el transportista. La opción que dice que no existe esta infracción es incorrecta, ya que la normativa sí la contempla.', 'Ley 16/1987 Art. 140.33'),
('cap-093cc572bb2d', 'Para las mujeres, en condiciones ideales de trabajo y levantando pesos en posición de pie, la cifra máxima aconsejada es de 15 kilogramos. Este límite se establece para prevenir lesiones musculoesqueléticas. Superar los 15 kilogramos aumenta significativamente el riesgo de sufrir daños en la espalda o en otras partes del cuerpo. La opción de 20 kilogramos es la cifra máxima aconsejada para los hombres, no para las mujeres.', NULL),
('cap-093fc567590d', 'El Reglamento Comunitario (CE) 561/2006 Art. 4.g establece que el descanso diario normal se puede dividir en dos períodos. El primero debe ser de al menos 3 horas ininterrumpidas y el segundo de al menos 9 horas ininterrumpidas. Por lo tanto, un descanso de 4 horas y 8 horas no es válido porque el segundo período no cumple el mínimo de 9 horas. La opción que dice que entre los dos períodos suman 12 horas es incorrecta, ya que la suma total no es el único requisito, sino también la duración mínima de cada parte.', 'Reglamento Comunitario (CE) 561/2006 Art. 4.g'),
('cap-09443c239030', 'La potencia es la capacidad del motor para realizar trabajo en un tiempo determinado, es decir, la rapidez con la que puede generar ese trabajo. El par motor, en cambio, es la fuerza de giro que el motor puede aplicar, pero no indica la velocidad a la que se realiza el trabajo. El consumo se refiere a la cantidad de combustible que utiliza el motor, no a su capacidad de trabajo. La relación de compresión es un parámetro de diseño del motor que influye en su eficiencia, pero no es la medida directa del trabajo por unidad de tiempo.', NULL),
('cap-0962bd745644', 'El humo negro indica una combustión incompleta, lo que significa que no hay suficiente aire para quemar todo el combustible. Esto suele ocurrir porque el filtro del aire está sucio y no deja pasar el aire necesario al motor. El filtro de gasoil o el de inyección, si estuvieran sucios, causarían problemas de suministro de combustible, lo que se manifestaría con tirones o falta de potencia, no con humo negro. El filtro de aceite no tiene relación directa con la combustión ni con el color del humo de escape.', NULL),
('cap-0965f2c81765', 'El certificado de conductor es un documento específico que acredita que un conductor de fuera de la UE o del Espacio Económico Europeo, sin residencia de larga duración, está autorizado para realizar transporte internacional público. Es un requisito indispensable para estos conductores en esa situación concreta. Los discos-diagrama son para tacógrafos analógicos, no digitales. La tarjeta de conductor es para el tacógrafo digital, no el analógico. El libro de ruta ya no es un documento obligatorio en el transporte internacional.', NULL),
('cap-096f7a821dba', 'La energía cinética es la energía que tiene un cuerpo por estar en movimiento. Cuanto mayor sea la velocidad del vehículo, mayor será su energía cinética. De igual forma, cuanto mayor sea la masa del vehículo, mayor será la energía cinética que acumula. Por eso, la energía cinética depende de la velocidad y la masa del vehículo. La altura no influye en la energía cinética, sino en la energía potencial.', NULL),
('cap-09764339b6b2', 'Todas las medidas mencionadas son precauciones fundamentales para evitar atropellos. Moderar la velocidad reduce la distancia de frenado y da más tiempo de reacción. No circular pegado a la acera evita sorpresas con peatones que puedan bajar o invadir la calzada. Prestar atención cuando un vehículo se detiene delante es crucial porque puede haber peatones cruzando por delante de ese vehículo. Ninguna de las otras opciones es incorrecta, ya que todas contribuyen a la seguridad.', NULL),
('cap-098f2e08b7fa', 'La inmovilización por minoración del descanso diario se levanta cuando el conductor cumple con las horas de descanso que le faltaban. El objetivo de la inmovilización es garantizar la seguridad en carretera, y esto se consigue cuando el conductor está en condiciones óptimas para conducir. La Ley 16/1987 Art. 143.4 establece la inmovilización por incumplimiento de los tiempos de descanso. La empresa no decide cuándo se levanta la inmovilización, ni tampoco el agente, sino que es una medida para corregir la infracción.', 'Ley 16/1987 Art. 143.4'),
('cap-09976b061b8c', 'Las marcas de identificación de los vehículos de temperatura controlada, según el acuerdo ATP, se componen exclusivamente de letras. Estas letras indican la clase del equipo y la temperatura máxima o mínima que puede mantener. Los números no forman parte de esta identificación principal.', NULL),
('cap-09ad12ee8a87', 'La ergonomía busca adaptar el puesto de trabajo a la persona para prevenir problemas de salud. Su objetivo principal es reducir la fatiga y las lesiones musculoesqueléticas, que son riesgos físicos. Mejorar las ganancias o beneficios económicos son consecuencias indirectas, no el objetivo fundamental de la ergonomía.', NULL),
('cap-09b525f2761d', 'Una concentración excesiva de señales es un elemento que está fuera del conductor, en el entorno de la vía, por lo que es un factor externo que puede sobrecargar la información visual y desviar la atención. Esto puede llevar a distracciones y dificultar la toma de decisiones. No es un factor interno porque no depende del estado físico o mental del conductor. No se limita solo a señales de prohibición, cualquier tipo de señal en exceso puede ser una distracción.', NULL),
('cap-09c52fe042d7', 'El cabotaje se refiere a la realización de transportes nacionales de mercancías por parte de un transportista extranjero. Esto significa que un camión de otro país realiza un servicio de transporte dentro de las fronteras de un único estado. La idea de que el cabotaje se limita a un radio de 300 km es incorrecta, ya que no hay una restricción de distancia específica para definirlo.', NULL),
('cap-09eea7d4cc72', 'Los conductores de los Cuerpos de Seguridad del Estado están exentos de tener el CAP. El RD 1032/2007 Art. 2 establece claramente esta exención para los vehículos utilizados por las Fuerzas y Cuerpos de Seguridad. No importa el tipo de vehículo que conduzcan ni la distancia, la exención es total para estos profesionales. La idea de que solo necesitan el CAP para autobuses o vehículos de mercancías es incorrecta, ya que la normativa no hace esa distinción.', 'RD 1032/2007 Art. 2'),
('cap-09f3b6e60860', 'El tacógrafo digital está diseñado para registrar la actividad del conductor, que incluye los tiempos de conducción, descanso, disponibilidad y otros trabajos. Esta información es fundamental para asegurar el cumplimiento de la normativa de tiempos de conducción y descanso, que busca mejorar la seguridad vial y las condiciones laborales. El Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado II, 1 (3821/85) especifica claramente los datos que deben registrarse. El consumo medio de carburante, las revoluciones del motor o el uso de la caja de cambios son datos que puede registrar la centralita del vehículo, pero no son un registro obligatorio del tacógrafo.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado II, 1 (3821/85)'),
('cap-0a079c61e036', 'La zona económica del motor se define por el régimen de revoluciones donde el motor ofrece su mejor rendimiento, es decir, la mayor potencia y par motor con el menor consumo de combustible. Es el punto óptimo para conducir de forma eficiente. Las características internas del motor, como la relación de compresión o la carrera del pistón, son datos de diseño del motor, no indicadores de su zona económica en el cuentarrevoluciones.', NULL),
('cap-0a4aa805ae13', 'El transporte de equipaje en un remolque arrastrado por un autobús no requiere autorización administrativa de transporte de mercancías. Esto se debe a que el equipaje de los viajeros no se considera mercancía a efectos de la normativa de transporte. La autorización de transporte de mercancías es para el transporte de bienes con fines comerciales. La opción de que solo sea para transportes internacionales es incorrecta, ya que la naturaleza del equipaje no cambia por la ruta.', 'RD 1211/1990 Art. 41'),
('cap-0a6152a2e131', 'Un aceite de alta calidad reduce la fricción entre las piezas del motor, lo que disminuye la resistencia interna y, por tanto, el esfuerzo necesario para moverlas. Menos esfuerzo significa que el motor necesita quemar menos carburante para realizar el mismo trabajo. La opción de que se dificulta la refrigeración del motor es incorrecta, ya que los aceites de calidad también contribuyen a disipar el calor.', NULL),
('cap-0a64b99cd32d', 'La afirmación de que los conductores profesionales tienen un grado de siniestralidad muy alto por su poca experiencia es incorrecta. Los conductores profesionales, por lo general, acumulan mucha experiencia al volante y están sujetos a formación continua, lo que reduce su siniestralidad. La siniestralidad de los conductores profesionales no se debe a la falta de experiencia, sino a otros factores como la fatiga o las presiones de los horarios. Es un error pensar que la siniestralidad se debe a la inexperiencia, ya que la formación y la práctica son constantes en esta profesión.', NULL),
('cap-0a6b0a6b4d43', 'El mantenimiento del vehículo, como filtros sucios o inyectores en mal estado, afecta directamente al consumo. El perfil de la carretera, con pendientes ascendentes o descendentes, exige más o menos potencia y, por tanto, más o menos carburante. Una presión incorrecta en los neumáticos aumenta la resistencia a la rodadura y, consecuentemente, el consumo. Los tipos de frenos o ralentizadores no influyen en el consumo de carburante.', NULL),
('cap-0a74cf0afa8b', 'El ejercicio físico regular es fundamental para mantener una buena salud general, y esto incluye la prevención de enfermedades del corazón y del sistema circulatorio. Un conductor profesional pasa muchas horas sentado, lo que aumenta el riesgo de estos problemas. Mantenerse activo ayuda a que el cuerpo funcione mejor y reduce el riesgo de sufrir un infarto o un ictus. Aunque el ejercicio mejora el bienestar general, no tiene un impacto directo en la capacidad de descifrar información de la carretera o asimilar estímulos del vehículo, que son habilidades más relacionadas con la atención y la experiencia.', NULL),
('cap-0ac03eca07ee', 'La desmultiplicación de la caja de cambios se refiere a cómo se transforma la velocidad de giro del motor para mover las ruedas. Es la relación entre los engranajes que conectan el motor con las ruedas, permitiendo adaptar la fuerza y la velocidad según las necesidades de la conducción. No se trata del número de velocidades, sino de la proporción de giro entre el motor y las ruedas en cada marcha. Tampoco se refiere al total de piñones de cada marcha, sino a la relación de tamaños entre ellos.', NULL),
('cap-0ac2da5c1eed', 'El sistema de reconocimiento de señales puede alertar al conductor de forma pasiva, por ejemplo, mostrando la señal en el cuadro de instrumentos. También puede actuar de forma activa, como ajustando automáticamente la velocidad del control de crucero adaptativo a la señal detectada. La opción de que solo sea pasiva es incorrecta porque los sistemas modernos ya integran funciones activas. La afirmación de que no interactúa es totalmente falsa, ya que su propósito es precisamente interactuar con el conductor o el vehículo.', NULL),
('cap-0af8044ef11e', 'Los transportes de cabotaje son aquellos que se realizan íntegramente dentro de un país extranjero, pero son llevados a cabo por un transportista que no está establecido en ese país. Es decir, un transportista de un país realiza un transporte nacional en otro país. La opción que menciona transportistas establecidos en el mismo Estado describe un transporte nacional normal, no de cabotaje.', 'Reglamento Comunitario (CE) 1072/2009 Art. 1;Art. 8'),
('cap-0b24e9b4ce28', 'Cuando un neumático se pincha, pierde presión y su diámetro disminuye ligeramente. Esto provoca que el vehículo se "caiga" un poco de ese lado, generando una tendencia a desviarse hacia la rueda afectada. La inclinación hacia atrás no es un síntoma de pinchazo, y una vibración importante en el volante suele indicar un problema de equilibrado o dirección, no un pinchazo.', NULL),
('cap-0b39df53872f', 'La comunicación de un curso CAP siempre se hace a la Administración de Transportes de la Comunidad Autónoma donde se va a impartir. Aunque la empresa tenga su sede principal en otro sitio, la sucursal debe comunicar el curso a la autoridad local. La Administración que autorizó a la empresa CAP no es la competente para supervisar cursos fuera de su territorio. No basta con tener los cursos homologados, siempre hay que comunicar su impartición a la autoridad competente del lugar.', NULL),
('cap-0b440bed07ea', 'Circular a una velocidad media más baja reduce el esfuerzo del motor, lo que se traduce en un menor consumo de combustible y, por tanto, menos emisiones contaminantes. Además, una conducción más tranquila y sin prisas mejora el confort para el conductor. La opción de reducir el coeficiente aerodinámico es incorrecta, ya que este es una característica del diseño del vehículo, no de la velocidad a la que se circula.', NULL),
('cap-0b471c78ac40', 'Para calcular el tiempo diario de conducción, debes tener en cuenta todas las horas que has conducido, tanto si ha sido dentro de la Unión Europea como si ha sido en un país que no pertenece a la UE. El Reglamento Comunitario (CE) 561/2006 Art. 6.4 es claro al respecto. No se trata solo de las horas en territorio comunitario, ni solo de las de un país tercero, sino de la suma de todas ellas. El Reglamento sí considera el tiempo diario de conducción, estableciendo límites claros.', 'Reglamento Comunitario (CE) 561/2006 Art. 6.4'),
('cap-0b4cfaabcb3e', 'La atomización empresarial, con muchas empresas pequeñas, dificulta la formación porque los conductores son esenciales para la operativa diaria y es complicado prescindir de ellos para que asistan a cursos. Las empresas grandes tienen más recursos para organizar la formación y cubrir las ausencias. La idea de que la atomización aumenta la capacidad inversora es incorrecta, ya que las empresas pequeñas suelen tener menos recursos financieros para invertir en mejoras o formación.', NULL),
('cap-0b4f3eed939e', 'El número de muertos en accidente de tráfico en España ha disminuido considerablemente en los últimos 30 años. Esto se debe a una combinación de factores como la mejora de la seguridad de los vehículos, el endurecimiento de las normativas de tráfico y una mayor concienciación de los conductores. Pensar que ha aumentado considerablemente es un error, ya que las políticas de seguridad vial han tenido un impacto positivo y medible.', NULL),
('cap-0b5d1ba61ec6', 'Para que un cliente esté satisfecho con un servicio de transporte, es fundamental cumplir con los elementos básicos que espera, como la entrega a tiempo y en buen estado. Si no se cumplen estos mínimos, el cliente estará insatisfecho, por muy bien que se cumplan otros aspectos. Los elementos proporcionales o atractivos son extras que pueden generar mayor satisfacción, pero no son imprescindibles para la satisfacción inicial. No todas las respuestas son correctas porque sin los elementos básicos, los demás no importan.', NULL),
('cap-0b63a3976929', 'Los retardadores son dispositivos auxiliares que se utilizan para mantener la velocidad del vehículo o reducirla sin necesidad de usar los frenos de servicio, evitando su sobrecalentamiento. La cadena cinemática y el árbol de transmisión son elementos de la transmisión de potencia del vehículo, no del sistema de frenado. Los discos y tambores son componentes de los frenos de servicio, que sí frenan el vehículo, pero no son ralentizadores auxiliares.', NULL),
('cap-0b703997f329', 'El consumo de carburante está directamente relacionado con la cantidad de combustible que se inyecta, lo cual controlamos con el pedal del acelerador. Un filtro de aire sucio restringe la entrada de aire al motor, lo que provoca una combustión ineficiente y, por tanto, un mayor consumo. Los ralentizadores no influyen directamente en el consumo de carburante, ya que su función es frenar el vehículo, no gestionar la combustión.', NULL),
('cap-0ba0b20dbc21', 'En caso de incendio y evacuación, todas las pautas mencionadas son correctas y necesarias. Es fundamental coger el extintor y usarlo correctamente para intentar sofocar el fuego. También es crucial comunicar instrucciones claras a los viajeros para una evacuación ordenada, evitando el pánico. Finalmente, velar por la seguridad de los viajeros impidiendo que vuelvan al vehículo en llamas es una medida de protección indispensable.', NULL),
('cap-0ba5dce6f3f3', 'Una conducción eficiente, que incluye anticipación, marchas adecuadas y evitar acelerones y frenazos bruscos, optimiza el uso del motor y reduce significativamente el consumo de carburante. Esto es aplicable a cualquier tipo de vehículo, no solo a los ligeros, y en cualquier tipo de vía. Una conducción relajada, si es eficiente, también reduce el consumo, no lo aumenta.', NULL),
('cap-0bcd60025cb0', 'El efecto "fading" es la pérdida de eficacia de los frenos por sobrecalentamiento, lo que significa que el vehículo frena menos, no que disminuya la velocidad automáticamente. Al aumentar la temperatura en los frenos, el coeficiente de rozamiento entre los forros disminuye y estos pueden cristalizarse, reduciendo la capacidad de frenado. Por lo tanto, la afirmación de que el efecto "fading" provoca que automáticamente disminuya la velocidad es falsa, ya que el conductor debe intervenir para reducirla. La cristalización de los forros es una consecuencia directa del sobrecalentamiento y la pérdida de eficacia.', NULL),
('cap-0be3cb1a0e98', 'Para subir una marcha, hay que aprovechar el par motor máximo, que es donde el motor entrega su mayor fuerza. Esta zona se indica en el cuentarrevoluciones con la zona verde, y es en la parte alta de esta zona donde se consigue la mayor eficiencia y potencia antes de cambiar. Cambiar por encima de 3000 o 3500 r.p.m. es demasiado alto y no es una referencia universal, ya que cada motor tiene su propio rango óptimo.', NULL),
('cap-0bed13d5e55d', 'En un control de carretera, el conductor siempre se considera representante de la empresa. Esto es así para la documentación que debe llevar a bordo y para la información que se le pida sobre el servicio. La Ley 16/1987 Art. 33.3 lo establece claramente. No es necesario que la empresa lo acredite específicamente para esta función, ni se limita a transportes internacionales.', 'Ley 16/1987 Art. 33.3'),
('cap-0c1c7a8929a7', 'Ante una tormenta eléctrica fuerte, lo más seguro es parar el vehículo y apagar el motor para evitar que un rayo pueda dañar el sistema eléctrico. Es importante no estacionar cerca de las vías del tren, ya que los raíles pueden conducir la electricidad de un rayo a distancia. No es una obligación legal detenerse, sino una medida de precaución. Dejar el motor conectado no es seguro porque aumenta el riesgo de daños eléctricos por un rayo.', NULL),
('cap-0c538c218ecc', 'Es fundamental que el conductor tenga una visibilidad completa de la carretera, los espejos y los indicadores para una conducción segura. Además, mantener una temperatura agradable y reducir el ruido al máximo en la cabina contribuyen a la concentración y a disminuir la fatiga. Todos estos factores son importantes para la seguridad y el confort del conductor profesional.', NULL),
('cap-0c60f945cafb', 'Los costes externos son los que genera el transporte pero no los paga directamente quien lo produce o lo consume, sino que recaen sobre toda la sociedad. Un ejemplo claro es la contaminación o el ruido. Las tarifas que aplican los transportistas son costes internos, ya que los paga directamente el cliente. Los costes subvencionables no son necesariamente externos, y los costes del transporte internacional fuera del país son costes operativos, no externos.', NULL),
('cap-0c68cc654b88', 'Las autorizaciones de transporte público de mercancías se otorgan a la empresa, no a un vehículo concreto ni por cada viaje. La OM FOM/734/2007 en su artículo 4 lo deja claro al hablar de la titularidad de la autorización y de las copias certificadas para cada vehículo de la empresa. La opción de "autorización por vehículo" es incorrecta porque lo que se expide por vehículo es una copia de la autorización de la empresa, no la autorización en sí misma.', 'OM FOM/734/2007 Art. 4'),
('cap-0c8e50993623', 'Con viento fuerte, usar una marcha corta te da más control sobre el vehículo y evita que el viento lo desplace. Esto se debe a que una marcha corta proporciona mayor retención del motor y más par motor disponible para contrarrestar la fuerza del viento. Aumentar la velocidad o sujetar levemente el volante son acciones peligrosas que reducen el control. Llevar las ventanillas abiertas no influye significativamente en la estabilidad del vehículo frente al viento.', NULL),
('cap-0ca09521c5b4', 'El IVMS es un sistema de gestión de flotas que recopila datos del vehículo y del conductor, lo que permite optimizar rutas y, por tanto, estimar con mayor precisión los tiempos de entrega. El DDR es un sistema de registro de datos de accidentes, no de gestión de tiempos. El RCTA es un sistema de alerta de tráfico cruzado trasero, y el ESS es un sistema de señalización de parada de emergencia, ninguno de los cuales tiene relación con la estimación de tiempos de entrega.', NULL),
('cap-0cd0bee8df4b', 'El gerente es el máximo responsable de la empresa y su función principal es la coordinación general de todas las áreas para asegurar el buen funcionamiento. También debe tomar las decisiones estratégicas que marcan el rumbo y el futuro de la empresa. Planificar servicios y rutas es una tarea más operativa, mientras que el seguimiento comercial es una función del departamento de ventas. La elaboración de nóminas es una tarea administrativa, no de gerencia, y no tiene sentido diferenciar entre personal fijo y eventual para esta función.', NULL),
('cap-0cdbcc8485ae', 'La tarjeta de inspección técnica es el documento que acredita que el vehículo ha superado las revisiones obligatorias y cumple con las condiciones técnicas para circular. Es fundamental para la seguridad vial y para verificar que el vehículo está en regla. Aunque el permiso de matriculación y la póliza de seguro son obligatorios, la tarjeta de inspección técnica es el documento específico que se refiere a la aptitud técnica del vehículo.', NULL),
('cap-0ce930891eb9', 'Las resistencias que se oponen al movimiento de un vehículo son la resistencia aerodinámica, que es la oposición del aire; la resistencia a la rodadura, que es la fricción de los neumáticos con el suelo; y la resistencia a la pendiente, que es la fuerza de la gravedad cuando el vehículo sube una cuesta. La termorresistencia no es una resistencia al movimiento del vehículo, sino un concepto relacionado con la temperatura.', NULL),
('cap-0d0f3cf72034', 'Cuando el motor retiene y las revoluciones están por encima del ralentí, la inyección electrónica corta completamente el suministro de combustible para ahorrar. Esto significa que el consumo de carburante es nulo en ese momento. El consumo no es igual que al ralentí, ya que en ralentí sí hay un consumo mínimo para mantener el motor encendido.', NULL),
('cap-0d13e7792281', 'La energía acumulada de un camión en movimiento, conocida como energía cinética, depende directamente de dos factores: la masa del vehículo y su velocidad. Cuanta más masa o más velocidad tenga el camión, mayor será su energía cinética. Por eso, un camión pesado y rápido tiene mucha más energía que uno ligero o lento. La velocidad influye de forma cuadrática, es decir, si duplicas la velocidad, la energía se cuadruplica, no solo se duplica. No depende solo de la velocidad, ya que la masa del vehículo es un factor igualmente crucial en la cantidad de energía que acumula.', NULL),
('cap-0d1da7523647', 'La percepción del riesgo es un factor interno porque depende directamente de cómo el conductor interpreta y valora las situaciones en la carretera, influenciada por su experiencia y estado mental. La velocidad es un factor externo que el conductor controla, pero no es un condicionante interno de su propia capacidad o estado. Una situación de tráfico compleja es un factor externo del entorno, no algo inherente al conductor. El estado de los neumáticos es un factor técnico del vehículo, no un condicionante interno del conductor.', NULL),
('cap-0d29eda9d157', 'Para formar una cooperativa de primer grado, la Ley 27/1999 Art. 8 establece que se necesitan al menos tres socios. Este es el mínimo legal para su constitución. La opción de cuatro, cinco o seis socios no es correcta porque la ley fija el umbral en tres.', 'Ley 27/1999 Art. 8'),
('cap-0d3796cf2450', 'Cuando la guiñada es excesiva para la velocidad en una curva, el eje trasero del vehículo pierde adherencia y tiende a deslizarse hacia el exterior de la curva, lo que se conoce como sobreviraje. Esto hace que el camión gire más de lo que el conductor pretende con el volante. El vehículo no permanece estable, ya que hay una pérdida de control direccional. Tampoco subvira, que es cuando el eje delantero pierde adherencia y el vehículo gira menos de lo esperado.', NULL),
('cap-0d3ed9d865b2', 'Un giro brusco o excesivo del volante, especialmente a velocidad, puede hacer que los neumáticos pierdan adherencia con la calzada, provocando que el vehículo patine o derrape. El bloqueo de una rueda directriz no es una consecuencia directa del manejo incorrecto del volante, sino más bien de un fallo en el sistema de dirección o frenos.', NULL),
('cap-0d46c494a9fa', 'Un motor mal reglado no funciona de forma eficiente, lo que provoca que necesite más carburante para producir la misma potencia. Esto se traduce directamente en un mayor gasto de combustible. Las opciones que sugieren una reducción del consumo son incorrectas, ya que un reglaje deficiente siempre perjudica la eficiencia del motor.', NULL),
('cap-0d4cd16b342a', 'La potencia es la capacidad del motor para realizar trabajo en un tiempo específico. Un motor más potente puede mover una carga más pesada o a mayor velocidad en el mismo intervalo. La velocidad máxima de trabajo no define la potencia, ya que un motor puede ser rápido pero tener poca fuerza. La cantidad de energía transmitida a las ruedas es el resultado de la potencia, no su definición.', NULL),
('cap-0d4d15acef27', 'Respetar las normas de circulación es la base para una conducción segura, ya que están diseñadas para prevenir accidentes y garantizar la fluidez del tráfico. Cumplir con ellas reduce significativamente los riesgos en la carretera. Conducir en cualquier condición física o psíquica es extremadamente peligroso y aumenta la probabilidad de sufrir un accidente.', NULL),
('cap-0d7a06e04094', 'Los accidentes laborales generan importantes gastos directos e indirectos, como costes médicos, indemnizaciones, daños materiales y pérdida de productividad. Estos costes afectan tanto a la empresa como al trabajador y a la sociedad en general. Las otras opciones son incorrectas porque un accidente laboral nunca mejora la motivación, las relaciones o la satisfacción; al contrario, suelen deteriorarlas.', NULL),
('cap-0d8251ef98fa', 'La atomización empresarial, que significa muchas empresas pequeñas, es un problema generalizado en el sector del transporte. Dificulta la inversión en vehículos modernos y tecnología, y reduce la capacidad de negociación frente a grandes clientes o proveedores. Esto afecta tanto al transporte de mercancías como al de viajeros, ya que las desventajas de la fragmentación son las mismas para ambos.', NULL),
('cap-0d8938480c53', 'Cuando cambias de vehículo y ambos usan tacógrafo analógico, debes anotar la lectura del cuentakilómetros del nuevo vehículo en el mismo disco-diagrama que ya estabas usando. Esto es fundamental para mantener un registro continuo y completo de tu actividad y los kilómetros recorridos, siempre que el disco sea válido para ambos vehículos. No es necesario anotarlo es incorrecto porque la normativa exige un registro completo de la actividad del conductor y del vehículo.', NULL),
('cap-0db50f2de8cf', 'Un vehículo de transporte de viajeros de más de 23 plazas, que no realiza transporte escolar, debe llevar un extintor de la clase 21A/113B. Este tipo de extintor es el adecuado para cubrir los riesgos de incendio más comunes en este tipo de vehículos. Llevar dos extintores de la clase 21A/113B sería excesivo para las necesidades de seguridad requeridas. Un extintor de la clase 8A/34B es insuficiente para la capacidad del vehículo.', NULL),
('cap-0dcd90b476af', 'El palé europeo o europalé tiene unas dimensiones estandarizadas de 1.200 x 800 milímetros. Esta medida es fundamental para la logística y el transporte de mercancías, ya que permite optimizar el espacio en camiones y almacenes. Conocer esta medida es crucial para la planificación de cargas y la eficiencia en la cadena de suministro. Otras medidas como 1.000 x 700 milímetros no corresponden al estándar del europalé.', NULL),
('cap-0df6c69a07e5', 'El sistema ASR evita que las ruedas motrices patinen al acelerar, mejorando la tracción del vehículo. Esto es crucial para mantener la estabilidad y la seguridad, especialmente en superficies resbaladizas o al arrancar con carga. No es un sistema de control de frenado, aunque use los frenos para su función, ni de dirección o navegación.', NULL),
('cap-0e09312ca44a', 'Las infracciones muy graves en materia de tiempos de conducción y descanso tienen un plazo de prescripción de tres años. Este periodo es el más largo para las sanciones, reflejando la seriedad de estas infracciones. Un plazo de dos años sería incorrecto, ya que ese es el periodo para las infracciones graves, no las muy graves.', NULL),
('cap-0e127ca4f736', 'Los cables y enchufes defectuosos son la causa más frecuente de quemaduras en el transporte porque pueden provocar cortocircuitos, sobrecalentamientos o chispas. Estos fallos eléctricos generan calor intenso que puede quemar directamente o iniciar incendios. La mala colocación de la carga no suele causar quemaduras directamente, sino más bien golpes o caídas.', NULL),
('cap-0e1291ad187b', 'Cuando la presión es excesiva, el neumático se hincha más por el centro, apoyándose principalmente en esa zona. Esto provoca un desgaste prematuro y mayor en la banda de rodadura central. Si el neumático se desgastara más por los bordes, sería indicativo de una presión insuficiente. El neumático siempre sufre deformaciones si la presión no es la correcta, y la presión no afecta directamente a la inutilización de los frenos.', NULL),
('cap-0e4fda8c6d37', 'El control de estabilidad es el sistema que ajusta la guiñada del camión para mantenerlo en la trayectoria deseada por el conductor. Actúa sobre los frenos de ruedas individuales o la potencia del motor para corregir desviaciones. La anchura o el dibujo del neumático, aunque importantes para el agarre, no son sistemas que modifiquen activamente la guiñada del vehículo.', NULL),
('cap-0e61b16feb00', 'Cuando la presión del neumático es baja, la superficie de contacto con la carretera aumenta, lo que incrementa la resistencia a la rodadura. Esta mayor resistencia obliga al motor a trabajar más para mantener la velocidad, resultando en un mayor consumo de combustible. La afirmación de que una presión baja disminuye el consumo es incorrecta, ya que el motor necesita más energía para mover el vehículo.', NULL),
('cap-0e74a9637b80', 'El par motor es la fuerza de giro que produce el motor. A ralentí, el motor está girando a las revoluciones más bajas posibles sin calarse, justo para mantenerse encendido y mover sus propios componentes internos. Por lo tanto, la fuerza de giro que produce en ese momento es la mínima necesaria. No es nulo ni cero porque el motor sigue funcionando y generando un mínimo de fuerza.', NULL),
('cap-0ea4222b3f36', 'Un aceite de baja calidad no lubrica bien, lo que aumenta la fricción entre las piezas del motor. Esta mayor fricción hace que el motor tenga que esforzarse más para funcionar, lo que se traduce en una pérdida de potencia y, por tanto, en un mayor consumo de carburante. Pensar que solo influye en el desgaste de las piezas es un error, ya que la fricción también afecta directamente al rendimiento y la eficiencia del motor.', NULL),
('cap-0ebb3b42a8e1', 'El par motor se genera en el motor, pero para que llegue a las ruedas y mueva el vehículo, tiene que pasar por la caja de cambios y el diferencial. Estos elementos multiplican o reducen el par según la marcha que lleves, es decir, según la relación de transmisión. Por eso, el par que finalmente llega a las ruedas depende directamente de esa relación. La temperatura de los gases de escape, la presión en el colector o el orden de encendido son factores del motor que no influyen directamente en la multiplicación del par una vez generado.', NULL),
('cap-0ece4a1619e1', 'La declaración amistosa de accidente es un documento fundamental para las aseguradoras, por eso debe ser lo más completa posible. Es necesario registrar la fecha y hora para situar el evento temporalmente, y un croquis ayuda a entender la dinámica del accidente. Los datos de los testigos son cruciales para verificar los hechos y aportar pruebas adicionales.', NULL),
('cap-0ef644d02d9d', 'Es fundamental revisar la presión de los neumáticos visualmente cada día antes de iniciar la marcha. Una presión incorrecta, ya sea por exceso o por defecto, afecta directamente la seguridad, el consumo de combustible y la vida útil del neumático. Esperar a un control semanal o cada 15.000 km es demasiado tarde para detectar problemas que pueden surgir en cualquier momento.', NULL),
('cap-0eff50812912', 'Los comburentes son sustancias que facilitan la combustión de otros materiales, por lo que utilizarlos para rellenar huecos en la carga sería extremadamente peligroso y podría provocar un incendio. La madera, la espuma de poliuretano y las bolsas de aire son materiales adecuados para calzar y rellenar huecos, ya que proporcionan estabilidad y protección a la carga. No se deben usar materiales que puedan reaccionar con la carga o que supongan un riesgo adicional.', NULL),
('cap-0f0bc8ba5dd4', 'Sí, es recomendable saltar marchas al reducir en determinadas circunstancias, como cuando la velocidad del vehículo es muy baja o la pendiente es muy pronunciada. Esto permite adaptar la marcha a la velocidad y al régimen del motor de forma más eficiente. No es cierto que se deba hacer para disminuir la acción del freno motor, ya que el freno motor es una ayuda importante en pendientes descendentes.', NULL),
('cap-0f2b35d02fed', 'Los arbitrajes de las Juntas Arbitrales de Transporte son un servicio público y, por tanto, son gratuitos para las partes. Esto no significa que no haya que pagar los gastos que se generen si se solicitan pruebas periciales o de otro tipo. La idea de que el reclamante o ambas partes deban asumir el coste es incorrecta, ya que el servicio de arbitraje en sí no tiene coste.', NULL),
('cap-0f372a0ab727', 'Las mercancías no pertenecientes a la Unión están bajo vigilancia aduanera hasta que se les asigna un nuevo estatuto aduanero, por ejemplo, si se despachan a libre práctica. También dejan de estar bajo vigilancia aduanera si abandonan el territorio de la Unión Europea. La vigilancia aduanera es un control necesario para asegurar el cumplimiento de la normativa. La opción que indica que es solo cuando se determina su estatuto aduanero es incorrecta porque la vigilancia se mantiene hasta que ese estatuto cambia, no solo se determina.', 'Reglamento Comunitario (UE) 952/2013 Art. 134'),
('cap-0f4c7b3c73c6', 'La estatura de un trabajador no influye en la imagen profesional de una empresa de transporte, ya que es una característica física inmutable y no está relacionada con la calidad del servicio. Sin embargo, la apariencia, la actitud hacia el cliente y los valores humanos sí son fundamentales, porque reflejan directamente la profesionalidad y el compromiso de la empresa. Pensar que la apariencia no es relevante es un error, ya que una buena presencia transmite seriedad y confianza.', NULL),
('cap-0f5e856be7c2', 'El tacógrafo digital identifica al usuario en el momento de introducir su tarjeta, ya que esta contiene los datos personales del conductor. Es el método principal y automático para que el tacógrafo registre quién está operando el vehículo. La identificación no se produce al introducir actividades manuales, ya que estas son acciones posteriores a la identificación inicial del conductor. Tampoco se identifica al hacer una descarga, pues la descarga es una operación de extracción de datos, no de identificación del usuario.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado III, 1 (3821/85)'),
('cap-0f61ca817f24', 'En una evacuación, la prioridad absoluta es la seguridad de los pasajeros. Por eso, lo primero es alejarlos del peligro y llevarlos a un lugar seguro. Rellenar partes o leer procedimientos son tareas secundarias que se harán después, cuando la seguridad esté garantizada. Llamar a hospitales es una acción que se realizará si hay heridos, pero la evacuación es lo primero.', NULL),
('cap-0f8837278028', 'El cinturón de seguridad debe pasar por el hombro para que sujete correctamente el tronco y el tórax en caso de impacto, distribuyendo la fuerza del golpe sobre una zona fuerte del cuerpo. Si pasara por el cuello, podría causar lesiones graves en caso de accidente. Las opciones que mencionan el abdomen o la zona pélvica se refieren a la parte inferior del cinturón, no a la parte alta.', NULL),
('cap-0f8c5e12f7fc', 'Un acuerdo bilateral en transporte internacional es un pacto entre dos países. Su objetivo es establecer las normas y condiciones específicas para el transporte de mercancías que se realice entre esos dos territorios. No se trata de un acuerdo entre empresas, sino entre los propios estados para facilitar y regular el flujo de mercancías. La opción que habla de acuerdos entre organismos internacionales es incorrecta porque un acuerdo bilateral siempre implica solo a dos países.', NULL),
('cap-0f9324df891b', 'Evitar aceleraciones y frenazos bruscos es clave para reducir el consumo porque cada vez que aceleras o frenas de golpe, el motor necesita más energía y, por tanto, más carburante. Una conducción suave y anticipada mantiene el motor en un régimen más eficiente. Aumentar las revoluciones del motor para aumentar la potencia, o usar marchas cortas para lo mismo, solo conseguiría disparar el consumo. Pisar el freno inmediatamente después de dejar de acelerar es un error porque desaprovecha la inercia del vehículo y obliga a volver a acelerar antes.', NULL),
('cap-0f9b93ac2957', 'El consumo específico se refiere a la cantidad de combustible que un motor necesita para producir una cierta cantidad de energía. Los fabricantes suelen expresar el consumo de combustible en litros por cada 100 kilómetros recorridos, ya que es la medida más estandarizada y fácil de entender para comparar la eficiencia de diferentes vehículos. Aunque la autonomía con depósito lleno es un dato útil, no es el consumo específico. Los litros a 100 km/h no es una medida de consumo, sino una condición de velocidad.', NULL),
('cap-0f9ca3f0d286', 'Las sociedades de responsabilidad limitada dividen su capital social en participaciones, que son indivisibles y acumulables. Esto las diferencia de las sociedades anónimas, que lo dividen en acciones. Las sociedades civiles no tienen un capital social dividido en participaciones, sino que se basan en las aportaciones de los socios.', NULL),
('cap-106c3e79a7ed', 'Para el transporte privado complementario, la clave es demostrar que el transporte es un complemento necesario de tu actividad principal, no la actividad en sí misma. Por eso, debes acreditar la necesidad de transportar las mercancías relacionadas con tu negocio. No basta solo con tener los vehículos, ya que el transporte privado complementario está ligado a la actividad principal de la empresa. Tampoco puedes ser titular de una autorización de transporte público, porque son incompatibles.', NULL),
('cap-107cf1c61639', 'El transporte privado complementario es un servicio que una empresa realiza para sí misma, como apoyo a su actividad principal, no para terceros. La Ley 16/1987 Art. 102 establece claramente que este tipo de transporte no puede ser contratado ni facturado de forma independiente. Su coste debe ir incluido en el precio del producto o servicio principal de la empresa. La idea de que se puede facturar si el volumen o la distancia superan ciertos límites es incorrecta, ya que la prohibición de facturar de forma independiente es absoluta para el transporte privado complementario.', 'Ley 16/1987 Art. 102'),
('cap-108322e364c0', 'Los discos-diagrama se conocen oficialmente como "hojas de registro". Así lo define el Reglamento Comunitario (UE) 165/2014 Art. 2.2 e, que especifica que es la hoja donde se graban los datos en un tacógrafo analógico. Las otras opciones, como "hojas de ruta" o "cuadros de servicio", no son la terminología correcta para referirse a estos elementos del tacógrafo.', 'Reglamento Comunitario (UE) 165/2014 Art. 2.2 e'),
('cap-1088f7720b93', 'La conducción económica implica anticipación y suavidad en el manejo, lo que reduce la necesidad de frenadas bruscas y aceleraciones repentinas. Estas técnicas, como mantener la distancia de seguridad y evitar maniobras agresivas, contribuyen directamente a una conducción más segura. Por lo tanto, la conducción económica no solo ahorra combustible, sino que también mejora la seguridad vial. La experiencia es importante, pero las técnicas de conducción económica son un factor directo en la mejora de la seguridad.', NULL),
('cap-109a72e22540', 'La marihuana es la droga ilegal más consumida en España, con una prevalencia significativamente mayor que otras sustancias. Aunque la cocaína también tiene un consumo extendido, no alcanza los niveles de la marihuana. El LSD y la heroína, por su parte, tienen un consumo mucho más marginal en comparación.', NULL),
('cap-10a33fcddcdf', 'Una puesta a punto adecuada del vehículo, que incluye la revisión de elementos como los filtros, la presión de los neumáticos y el sistema de inyección, asegura que el motor funcione de manera eficiente. Esto optimiza la combustión y reduce la resistencia al avance, lo que se traduce directamente en un menor consumo de carburante. El tipo de carburante no es el factor determinante en el ahorro, sino el estado del vehículo.', NULL),
('cap-10a4a4d39046', 'Los motores eléctricos en vehículos pesados son de corriente alterna porque ofrecen mayor eficiencia, potencia y un mejor control de la velocidad y el par motor, lo que es crucial para mover grandes cargas. La corriente alterna permite un diseño más robusto y sin escobillas, reduciendo el mantenimiento. Los motores de corriente continua son menos eficientes y más complejos de controlar en aplicaciones de alta potencia.', NULL),
('cap-10a550e5b910', 'Evitar acelerones y frenazos innecesarios es la técnica más efectiva para optimizar el consumo porque mantiene el motor en un régimen de revoluciones más constante y eficiente. Cada vez que aceleras bruscamente o frenas, el motor tiene que trabajar más para recuperar la velocidad, lo que aumenta el gasto de combustible. Circular siempre en marchas cortas es un error porque fuerza el motor a trabajar a revoluciones muy altas, disparando el consumo.', NULL),
('cap-10bdfc125458', 'Los albaranes de entrega del último servicio efectuado no son documentación obligatoria que deba llevarse siempre en el vehículo. Aunque son importantes para la gestión de la empresa, no son exigibles por las autoridades en un control en carretera. El permiso o licencia del conductor, el permiso de circulación y la ficha técnica son documentos esenciales que siempre deben acompañar al vehículo y al conductor.', NULL),
('cap-10c945adce16', 'El transporte realizado por una Administración pública para sus propias necesidades internas se denomina transporte oficial. Aunque la Ley 16/1987 Art. 105 los considera servicios privados complementarios, los exime de la autorización de transporte. La opción de transporte administrativo no es una categoría legal reconocida en la normativa de transporte. No es transporte público porque no se ofrece a terceros, ni transporte público complementario, que es una categoría diferente.', 'Ley 16/1987 Art. 105'),
('cap-10e696f6f009', 'El porteador, como profesional del transporte, tiene la responsabilidad de asegurar que la carga se realice de forma segura y correcta. Por ello, puede y debe dar instrucciones para garantizar la seguridad de la operación y la integridad de la mercancía. La OM FOM/1882/2012 Anexo, 4.14, aunque no lo dice explícitamente, se refiere a las responsabilidades del porteador. No es cierto que solo pueda dar instrucciones si lo exige el contrato o si el cargador está ausente, ya que su implicación en la seguridad de la carga es una obligación inherente a su profesión.', 'OM FOM/1882/2012 Anexo, 4.14'),
('cap-10f2501e3994', 'Los discos-diagrama son elementos clave para el registro de datos en los tacógrafos analógicos. Para asegurar su correcto funcionamiento y la fiabilidad de los registros, deben ser compatibles con el tacógrafo. Esta compatibilidad se garantiza mediante la marca de homologación del tacógrafo, que debe estar impresa en el disco-diagrama. El Reglamento Comunitario (UE) 165/2014 Anexo I, apartado IV, c, establece los requisitos para los discos-diagrama, incluyendo la necesidad de que lleven impresa la marca de homologación de los tacógrafos para los que sirven. No es relevante que el disco lleve la marca del vehículo o el nombre de la empresa, ya que el disco se asocia al tacógrafo, no al vehículo o a la empresa. Tampoco es el número de serie del tacógrafo, sino su homologación.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado IV, c'),
('cap-1110a6559913', 'La estiba busca asegurar la carga para que no se mueva durante el transporte, lo que podría causar daños a la mercancía, al vehículo o, lo más importante, a las personas. Una carga bien estibada garantiza la máxima seguridad para el conductor y otros ocupantes del vehículo. Colocar la carga de forma longitudinal no es suficiente para asegurar la estabilidad, ya que también debe ir sujeta para evitar movimientos. Dejar espacios entre los bultos, ya sea de uno o cuatro centímetros, es incorrecto porque la carga debe ir lo más compacta posible y bien sujeta para evitar cualquier desplazamiento.', NULL),
('cap-1127ddf4f081', 'Los camiones de poca potencia y corto recorrido necesitan un número de marchas suficiente para adaptarse a diferentes situaciones de carga y terreno, pero sin la complejidad de las cajas de cambios de vehículos más potentes. Un rango de entre 6 y 9 velocidades les permite optimizar el consumo y la fuerza. Las opciones con menos velocidades son insuficientes para la versatilidad que se requiere incluso en el transporte de corto recorrido.', NULL),
('cap-1131f98c194f', 'La Ley Orgánica 4/2000 Art. 55 establece que las infracciones muy graves se sancionan con multas que van desde los 10.001 hasta los 100.000 euros. El incumplimiento de la obligación de hacerse cargo de extranjeros con documentación deficiente es una infracción muy grave. Las opciones de pena de prisión menor o mayor no son correctas, ya que la normativa de extranjería contempla sanciones económicas para este tipo de infracciones. La incautación de la flota no es la sanción principal para este caso, aunque sí se contempla para otras infracciones muy graves relacionadas con el transporte ilegal de personas.', 'Ley Orgánica 4/2000 Art. 55'),
('cap-113fac02977c', 'La DGT establece restricciones para vehículos pesados, pero suele eximir a aquellos que realizan servicios esenciales o de interés público. Los vehículos de Correos, las grúas de auxilio en carretera y los que transportan animales vivos entran en esta categoría de exenciones. Por ejemplo, las grúas son vitales para despejar vías y los transportes de animales vivos requieren continuidad para el bienestar animal. Por tanto, todas las opciones mencionadas son correctas.', NULL),
('cap-11813c05b03c', 'El protocolo de actuación ante emergencias que se desarrolla en las fases de proteger, avisar y socorrer se conoce como PAS, que es el acrónimo de estas tres acciones. Es un procedimiento estandarizado para saber cómo actuar correctamente en caso de accidente o incidente. El protocolo médico es un concepto más amplio que abarca la atención sanitaria, no solo la secuencia inicial de actuación.', NULL),
('cap-11aa08a61127', 'La fatiga y el estrés son factores psíquicos que afectan directamente la capacidad de atención y reacción del conductor. Estos estados alteran la percepción del riesgo y la toma de decisiones, aumentando la probabilidad de sufrir un accidente. Por lo tanto, los factores psíquicos son elementos que contribuyen a los accidentes en el transporte. Decir que los accidentes siempre son físicos es un error, ya que muchos tienen un origen en el estado mental del conductor.', NULL),
('cap-11d9ab1d06ed', 'Para ahorrar combustible en un motor diésel, debes cambiar a una marcha más larga cuando el motor esté en su rango de par óptimo, que suele ser entre 1.500 y 2.000 revoluciones por minuto. Esto permite que el motor trabaje de forma eficiente, sin forzarlo ni revolucionarlo en exceso. Mantener el motor en este rango evita un consumo innecesario de combustible. Cambiar a marchas cortas con bajas revoluciones no es eficiente y puede forzar el motor.', NULL),
('cap-11ee49936a48', 'La demanda de potencia en las ruedas de un vehículo está directamente influenciada por la velocidad, ya que a mayor velocidad se requiere más potencia para superar resistencias. El perfil de la vía, como pendientes o descensos, también afecta significativamente la potencia necesaria. Además, la carga transportada incrementa la masa del vehículo, lo que exige más potencia para moverlo. Por lo tanto, todas las opciones mencionadas son factores determinantes.', NULL),
('cap-11faebcd3979', 'El tipo de vehículos que circulan te da información crucial sobre la densidad del tráfico, la velocidad media esperada y posibles maniobras de otros conductores. Por ejemplo, no es lo mismo circular con muchos turismos que con vehículos pesados o agrícolas. Las condiciones de luz, el trazado de la vía y la señalización son información del entorno o de la infraestructura, no directamente de las condiciones del tráfico en sí.', NULL),
('cap-1201d2a52367', 'La conducción eficiente implica anticipación, suavidad en el manejo y mantenimiento de distancias de seguridad, lo que reduce la probabilidad de situaciones de riesgo. Al evitar aceleraciones y frenadas bruscas, el conductor tiene más tiempo para reaccionar ante imprevistos. Por el contrario, pensar que la conducción eficiente reduce la seguridad es un error, ya que precisamente sus principios buscan un manejo más controlado y predecible del vehículo.', NULL),
('cap-1203f2cf4797', 'Un transporte intermodal es aquel que utiliza dos o más modos de transporte, como el vehículo y el avión, sin que la mercancía se manipule al cambiar de modo. La clave es que la unidad de carga, como un contenedor o caja móvil, es la que se transborda entre los diferentes medios. No es un transporte multiforma, ya que ese término no existe en la terminología del transporte.', NULL),
('cap-121d6b480a25', 'El extintor de CO2 es el más adecuado porque el dióxido de carbono no es conductor de la electricidad y no deja residuos, lo que es crucial en equipos eléctricos. Otros extintores, como el de polvo químico, pueden dañar los componentes electrónicos y dejar un residuo corrosivo. El agua pulverizada es peligrosa en fuegos eléctricos por su conductividad.', NULL),
('cap-123e39d2761c', 'La presión de los neumáticos debe ser siempre la recomendada por el fabricante, independientemente de la estación del año. Las variaciones de temperatura ambiente ya están consideradas en las especificaciones del fabricante. Mantener la presión correcta es crucial para la seguridad y el ahorro de combustible. Variar la presión según el tiempo de uso o los kilómetros de rodaje no es el criterio adecuado.', NULL),
('cap-1252f866a5a7', 'Los transitarios son las empresas especializadas en organizar transportes internacionales de mercancías por cuenta ajena, incluyendo las gestiones aduaneras y logísticas. Así lo establece la Ley 16/1987 Art. 121. Los agentes de aduanas se centran solo en los trámites aduaneros, no en la organización completa del transporte. Los gestores internacionales y los agentes de inspección no son términos que definan esta función específica en el transporte.', 'Ley 16/1987 Art. 121'),
('cap-12547e97dbe6', 'Para optimizar el consumo de carburante, la técnica más correcta es pedir al motor menos potencia. Esto se consigue conduciendo de forma suave, anticipando las situaciones del tráfico y evitando aceleraciones bruscas. Circular siempre en marchas cortas fuerza el motor y aumenta el consumo, no lo optimiza.', NULL),
('cap-12630327f0bd', 'La carga útil es la masa de mercancía que el camión puede transportar legalmente, y se obtiene restando la tara (el peso del vehículo vacío) de la Masa Máxima Autorizada (el peso máximo que el vehículo puede alcanzar). La masa neta de transporte no es un término técnico usado en el transporte de mercancías para este concepto. Las otras opciones no se refieren a la capacidad de carga del vehículo.', NULL),
('cap-1268c84bb43c', 'La potencia del motor está directamente relacionada con las revoluciones por minuto (RPM). A medida que aumentan las RPM, el motor puede generar más potencia, hasta alcanzar su punto máximo. Después de ese punto, si las RPM siguen subiendo, la potencia puede empezar a disminuir. La potencia no aumenta al cambiar a una marcha más larga, ya que eso reduce las RPM del motor.', NULL),
('cap-126c77a80ac5', 'La afirmación de que el cliente depende de la empresa y no la empresa del cliente no es cierta. En el transporte, la empresa depende del cliente para su existencia y rentabilidad, ya que sin clientes no hay negocio. El cliente es el centro de la actividad y su satisfacción es clave para la continuidad de la empresa. Las otras afirmaciones son correctas porque la percepción de calidad, la satisfacción de necesidades y el hecho de ser el propósito del trabajo son fundamentales en la relación con el cliente.', NULL),
('cap-1277bf8257b0', 'Los peajes para vehículos pesados se modulan en base a la categoría EURO de emisión para incentivar el uso de vehículos menos contaminantes. Esta medida busca reducir el impacto ambiental del transporte por carretera. Así, los vehículos más antiguos y contaminantes pagan más, mientras que los más modernos y eficientes pagan menos. La potencia del motor no es un factor directo para la modulación de peajes.', NULL),
('cap-12807b95f33f', 'Circular con marchas cortas implica que el motor trabaja a un régimen de revoluciones más alto para mantener una velocidad determinada, lo que aumenta el consumo de carburante. Para un consumo eficiente, es mejor usar marchas largas siempre que sea posible y las condiciones lo permitan. El consumo no disminuye a elevado número de revoluciones, sino que generalmente aumenta. El consumo de carburante no produce un par máximo muy alto, sino que el par motor es una característica del motor.', NULL),
('cap-128825a322f8', 'El sistema EBS es un sistema electrónico que gestiona el frenado de forma integral. Su principal ventaja es que consigue que los frenos actúen de manera inmediata y simultánea en todas las ruedas, lo que se traduce en una frenada más uniforme y eficaz. Por lo tanto, todas las afirmaciones sobre su funcionamiento son correctas.', NULL),
('cap-128ed981cdce', 'Si la suma de fuerzas y pares no es cero, significa que hay una fuerza neta actuando sobre el camión. Esta fuerza neta, o resultante, es la que provoca el movimiento del vehículo. El camión se moverá en la misma dirección en la que actúe esa fuerza resultante. Que se encontrara en reposo es incorrecto, ya que el reposo implica que la suma de fuerzas es cero.', NULL),
('cap-129ce7b82e30', 'Las autorizaciones bilaterales son acuerdos entre dos países que permiten a los transportistas de uno operar en el otro, ya sea para cargar o descargar mercancías, o simplemente para cruzar su territorio. Esto facilita el comercio y el tránsito internacional entre las naciones implicadas. La opción que menciona un conductor de un país tercero es incorrecta, ya que la bilateralidad se refiere a los países de origen y destino del transporte. Tampoco se limitan solo a transitar, sino que también permiten operaciones de carga y descarga. Finalmente, no habilitan para contratar transportistas de otros países, sino para realizar el transporte directamente.', 'OM 04/04/2000 Art. 5'),
('cap-129d69fff6b1', 'Observar el cuentarrevoluciones te permite cambiar de marcha en el régimen óptimo del motor, lo que reduce el consumo de combustible. Cada motor tiene una zona de revoluciones donde es más eficiente, y mantenerlo ahí es clave para el ahorro. Bajar pendientes en punto muerto es peligroso porque pierdes el control del vehículo y no ahorras combustible. Circular con presión de neumáticos inferior a la recomendada aumenta la resistencia a la rodadura y, por tanto, el consumo.', NULL),
('cap-12ad561b267e', 'El efecto "fading" es la pérdida de eficacia de los frenos de servicio por sobrecalentamiento. Para evitarlo en pendientes descendentes, hay que usar los sistemas de frenado auxiliares, como el ralentizador, que no dependen de la fricción de las pastillas. Mantener pisado fuertemente el pedal del freno es precisamente lo que provoca el sobrecalentamiento y el "fading".', NULL),
('cap-12b08b0e0101', 'La somnolencia diurna excesiva es un problema de salud que afecta directamente a la capacidad de atención y reacción al volante. Por eso, puede ser un impedimento tanto para conseguir el permiso de conducir por primera vez como para renovarlo. Incluso, si se considera que el riesgo es moderado, se puede optar por reducir el tiempo de validez del permiso para hacer un seguimiento más frecuente. Pensar que solo afecta a la obtención o a la prórroga es un error, ya que la seguridad vial es prioritaria en ambos casos.', NULL),
('cap-12ff5734569c', 'El viento lateral ejerce una fuerza sobre el vehículo que puede provocar que se desplace de su trayectoria o, en casos extremos, que vuelque, especialmente si el vehículo es alto o lleva poca carga. Este riesgo es mayor en vehículos de grandes dimensiones como los camiones. La pérdida de visibilidad puede ocurrir con lluvia o nieve, pero no es un efecto directo del viento en sí mismo.', NULL),
('cap-13091c815184', 'Los tiempos de conducción diaria y semanal deben incluir todas las horas de conducción, tanto si se realizan dentro de la Unión Europea como en cualquier país tercero. Esto lo establece claramente el Reglamento Comunitario (CE) 561/2006 Art. 6.4. No se limita solo a la Unión Europea o a los países firmantes de acuerdos específicos como el AETR o el CMR, sino que abarca cualquier territorio. La opción que menciona solo las conducciones dentro de la Unión Europea es incorrecta porque no considera la totalidad de la actividad del conductor.', 'Reglamento Comunitario (CE) 561/2006 Art. 6.4'),
('cap-1313a3e82b4a', 'Los vehículos de mercancías de más de 3.500 kg son los que más kilómetros recorren anualmente y, por su tamaño y peso, tienen una mayor inercia y puntos ciegos, lo que aumenta la probabilidad de verse implicados en accidentes. Los camiones de hasta 3.500 kg, aunque son numerosos, suelen tener un uso más urbano o de reparto, con menos kilómetros y velocidades más bajas. Los autobuses, tanto de línea regular como escolar, tienen una siniestralidad menor debido a las rutas fijas, velocidades controladas y la formación específica de sus conductores.', NULL),
('cap-13250e266af8', 'Seleccionar la marcha adecuada permite que el motor trabaje en su rango óptimo de revoluciones, lo que reduce el consumo. El perfil de la carretera, con sus pendientes y descensos, obliga al motor a realizar un mayor o menor esfuerzo, impactando directamente en la cantidad de carburante que necesita. El motor de arranque solo se usa para encender el motor y no influye en el consumo durante la marcha.', NULL),
('cap-1360264a78ad', 'Están exentos de la cualificación inicial del CAP los conductores que ya tenían un permiso de conducir de las categorías C1, C1+E, C o C+E antes del 11 de septiembre de 2009. Esto se debe a que la normativa del CAP entró en vigor para el transporte de mercancías en esa fecha, y se estableció una exención para quienes ya eran conductores profesionales. Los permisos D1+E o D+E se refieren al transporte de viajeros, no de mercancías, y tienen otras fechas de aplicación. Los permisos expedidos después de esa fecha sí requieren la cualificación inicial.', 'RD 1032/2007 Disposición transitoria 1ª'),
('cap-138bedf0e584', 'La marcha atrás está diseñada para mover el vehículo con la máxima fuerza a muy baja velocidad, lo que implica la mayor desmultiplicación y la convierte en la marcha más corta. Esto es necesario para maniobrar el vehículo en espacios reducidos o para superar pequeñas resistencias al retroceder. La primera velocidad, aunque también es muy corta, no alcanza el nivel de desmultiplicación de la marcha atrás.', NULL)
) as v(id, explicacion, norma)
where preguntas.id = v.id::text;
